const pipelineCaseCounts = `-- name: PipelineCaseCounts :many
SELECT c.pipeline_id::uuid AS pipeline_id,
       count(*) FILTER (WHERE c.terminal_kind IS NULL)::bigint AS open_cases,
       count(*) FILTER (WHERE c.terminal_kind IS NULL AND s.kind = 'review')::bigint AS in_review,
       count(*)::bigint AS total
FROM cases c JOIN pipeline_stages s ON s.id = c.stage_id
WHERE c.company_id = $1 AND c.pipeline_id IS NOT NULL
GROUP BY c.pipeline_id
`

type PipelineCaseCountsRow struct {
	PipelineID uuid.UUID
	OpenCases  int64
	InReview   int64
	Total      int64
}

// Por pipeline: cases abertos (não terminais) e, deles, os que estão numa etapa de revisão.
func (q *Queries) PipelineCaseCounts(ctx context.Context, companyID uuid.UUID) ([]PipelineCaseCountsRow, error) {
	rows, err := q.db.Query(ctx, pipelineCaseCounts, companyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PipelineCaseCountsRow{}
	for rows.Next() {
		var i PipelineCaseCountsRow
		if err := rows.Scan(
			&i.PipelineID,
			&i.OpenCases,
			&i.InReview,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

